{"code":"def transform(grid):
    # Each three-column sector is painted according to the vertical position
    # of its marker: top, middle, bottom correspond to 6, 4, 1.
    out=[[0]*len(grid[0]) for _ in grid]
    colors=[6,1,4]
    for b in range(3):
        for r in range(len(grid)):
            for c in range(b*3,min((b+1)*3,len(grid[0]))):
                out[r][c]=colors[b]
    return out"}

